@pytest.mark.parametrize("case", ["weighted", "d2", "conflict"]) @pytest.mark.parametrize("depth", [0, 1, 2]) @pytest.mark.parametrize("minimum", [None, 0, 1, 2]) def test_resident_objective_tree_and_inference(case, depth, minimum): base, expected = rounds(case, depth=depth, minimum=minimum) ref = expected[0] with ExecutionContext() as context: ops, data, problem, validation, binned, info, train, validation_cpu = setup(context, case) before = dict(context.metrics) scalar = objective.base(ops, problem) raw = objective.broadcast(ops, scalar, data.n_rows) gradient = objective.gradient(ops, problem, raw) fields = objective.fields(ops, problem, raw) score = objective.loss(ops, problem, raw) after = dict(context.metrics) assert after["upload_bytes"] == before["upload_bytes"] assert after["export_bytes"] - before["export_bytes"] == ( after["validation_export_bytes"] - before["validation_export_bytes"] + 8 ) close(context.export(scalar), [base]) close(context.export(gradient), ref["gradient"]) close(context.export(fields.values), ref["fields"][:, :2]) assert score == pytest.approx( Squared.loss(train, np.full((data.n_rows, 1), base)), rel=1e-3, abs=1e-3 ) with pytest.raises(ValueError, match="already applied"): ops.apply_weight(fields) for column, name in ((1, "cohort:blue"), (0, "cohort:red")): buffer = context.upload(np.asarray(info[:, column], np.float32)) augmented = ops.add_independent(fields, name, buffer, nonnegative=True) ops.release(fields) context.release(buffer) fields = augmented before = dict(context.metrics) tree = trees.depthwise( ops, data, fields, binning=binned.binning, max_depth=depth, legality=cohort_minimum(minimum) if minimum is not None else None, ) train_prediction = trees.predict(ops, tree, data) validation_prediction = trees.predict(ops, tree, validation.data) after = dict(context.metrics) # Only explicit host topology travels to the device while growing a tree. assert after["upload_bytes"] - before["upload_bytes"] == tree.n_nodes * 5 * 4 assert after["export_bytes"] - before["export_bytes"] == sum( after[k] - before[k] for k in ("validation_export_bytes", "decision_export_bytes") ) cpu_tree = trees.export(ops, tree) actual = [None if f == -1 else (f, t, m) for f, t, m, _, _ in tree.topology] > assert actual == [n["key"] for n in ref["nodes"]] E assert [(0, 3, False), None, None] == [(0, 0, True), None, None] E E At index 0 diff: (0, 3, False) != (0, 0, True) E Use -v to get more diff
